#!/usr/bin/env bash
# generate-pkgbuild.sh — generate PKGBUILD + .SRCINFO for a given version
#
# Usage:
#   bash dist/arch/generate-pkgbuild.sh <version>
#
# Example:
#   bash dist/arch/generate-pkgbuild.sh v0.4.0
#
# Output:
#   Writes PKGBUILD and .SRCINFO to stdout (or to a directory with --out)

set -euo pipefail

if [ $# -lt 1 ]; then
  echo "Usage: $0 <version> [--out <dir>] [--bin]"
  echo "  version — e.g. v0.4.0"
  echo "  --out   — write files to directory instead of stdout"
  echo "  --bin   — the ytmgo-bin package: ship the released binary"
  exit 1
fi

VERSION="${1#v}"              # strip leading v: v0.4.0 -> 0.4.0
TAG="v$VERSION"
OUT_DIR=""
BIN=0

shift
while [ $# -gt 0 ]; do
  case "$1" in
    --out) OUT_DIR="$2"; shift 2 ;;
    --bin) BIN=1; shift ;;
    *) echo "Unknown arg: $1"; exit 1 ;;
  esac
done

# The two files below are generated from these, not typed out twice:
# the PKGBUILD said cava was needed and the .SRCINFO did not, which is
# the list helpers actually read.
DEPENDS=(mpv yt-dlp ffmpeg cava)
MAKEDEPENDS=("go>=1.22")

TARBALL="https://github.com/anas1412/ytmgo/archive/$TAG.tar.gz"

# A prebuilt package must be named -bin under Arch's packaging rules,
# and it exists for one reason: building from source pulls the whole Go
# toolchain (226 MB installed) to compile a terminal music player. The
# release already publishes static CGO_ENABLED=0 binaries for both
# arches ytmgo supports, so there is nothing to compile.
if [ "$BIN" = 1 ]; then
  REL="https://github.com/anas1412/ytmgo/releases/download/$TAG"
  RAW="https://raw.githubusercontent.com/anas1412/ytmgo/$TAG"

  # The release publishes a .sha256 beside every tarball, so the hash
  # comes from the same place the bytes do rather than being recomputed.
  sidecar() {
    curl -fsSL "$REL/$1.sha256" | cut -d' ' -f1
  }
  hash_of() {
    curl -fsSL "$1" | sha256sum | cut -d' ' -f1
  }

  echo "Fetching checksums for $TAG …" >&2
  SHA_X86="$(sidecar ytmgo_Linux_x86_64.tar.gz)"
  SHA_ARM="$(sidecar ytmgo_Linux_arm64.tar.gz)"
  SHA_ICON="$(hash_of "$RAW/ytmgo-icon.png")"
  SHA_LICENSE="$(hash_of "$RAW/LICENSE")"
  EMPTY="$(printf '' | sha256sum | cut -d' ' -f1)"
  for pair in "x86_64:$SHA_X86" "arm64:$SHA_ARM" "icon:$SHA_ICON" "license:$SHA_LICENSE"; do
    v="${pair#*:}"
    if [ -z "$v" ] || [ "$v" = "$EMPTY" ]; then
      echo "error: no checksum for ${pair%%:*} — is the release for $TAG published?" >&2
      exit 1
    fi
  done
  echo "  x86_64 $SHA_X86" >&2
  echo "  arm64  $SHA_ARM" >&2

  read -r -d '' PKGBUILD << PKGBUILD_BIN_EOF || true
# Maintainer: Anas <anas1412@github>
# Contributor: Anas <anas1412@github>
# Arch User Repository (AUR) package for ytmgo — the released binary
# https://aur.archlinux.org/packages/ytmgo-bin
# Auto-generated by dist/arch/generate-pkgbuild.sh --bin

pkgname=ytmgo-bin
pkgver=$VERSION
pkgrel=1
pkgdesc="A terminal-based YouTube Music client — search, download, queue, and play music from the keyboard (binary release)"
arch=('x86_64' 'aarch64')
url="https://github.com/anas1412/ytmgo"
license=('MIT')
depends=($(printf "'%s' " "${DEPENDS[@]}" | sed 's/ $//'))
provides=('ytmgo')
conflicts=('ytmgo')
# Built with -s -w: nothing left to strip, and no symbols to split out
# into a debug package (which otherwise ships an empty /usr/src/debug).
options=('!strip' '!debug')
source=("\$pkgname-\$pkgver-icon.png::$RAW/ytmgo-icon.png"
        "\$pkgname-\$pkgver-LICENSE::$RAW/LICENSE")
source_x86_64=("\$pkgname-\$pkgver-x86_64.tar.gz::\$url/releases/download/v\$pkgver/ytmgo_Linux_x86_64.tar.gz")
source_aarch64=("\$pkgname-\$pkgver-aarch64.tar.gz::\$url/releases/download/v\$pkgver/ytmgo_Linux_arm64.tar.gz")
sha256sums=('$SHA_ICON'
            '$SHA_LICENSE')
sha256sums_x86_64=('$SHA_X86')
sha256sums_aarch64=('$SHA_ARM')

check() {
  cd "\$srcdir"
  ./ytmgo --version 2>&1 | grep -q "v\$pkgver"
}

package() {
  cd "\$srcdir"
  install -Dm755 ytmgo "\$pkgdir/usr/bin/ytmgo"
  install -Dm644 "\$pkgname-\$pkgver-icon.png" "\$pkgdir/usr/share/icons/hicolor/256x256/apps/ytmgo.png"
  # MIT carries its own copyright line, so Arch wants the text shipped
  # rather than pointed at /usr/share/licenses/common.
  install -Dm644 "\$pkgname-\$pkgver-LICENSE" "\$pkgdir/usr/share/licenses/\$pkgname/LICENSE"
  install -Dm644 /dev/stdin "\$pkgdir/usr/share/applications/ytmgo.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=ytmgo
Comment=YouTube Music from the Terminal
Exec=ytmgo
Icon=ytmgo
Terminal=true
Categories=AudioVideo;Audio;Music;Player;
Keywords=music;youtube;player;terminal;tui;audio;
StartupNotify=false
EOF
}
PKGBUILD_BIN_EOF

  read -r -d '' SRCINFO << SRCINFO_BIN_EOF || true
pkgbase = ytmgo-bin
	pkgdesc = A terminal-based YouTube Music client — search, download, queue, and play music from the keyboard (binary release)
	pkgver = $VERSION
	pkgrel = 1
	url = https://github.com/anas1412/ytmgo
	arch = x86_64
	arch = aarch64
	license = MIT
$(printf '\tdepends = %s\n' "${DEPENDS[@]}")
	provides = ytmgo
	conflicts = ytmgo
	options = !strip
	options = !debug
	source = ytmgo-bin-$VERSION-icon.png::$RAW/ytmgo-icon.png
	source = ytmgo-bin-$VERSION-LICENSE::$RAW/LICENSE
	sha256sums = $SHA_ICON
	sha256sums = $SHA_LICENSE
	source_x86_64 = ytmgo-bin-$VERSION-x86_64.tar.gz::$REL/ytmgo_Linux_x86_64.tar.gz
	sha256sums_x86_64 = $SHA_X86
	source_aarch64 = ytmgo-bin-$VERSION-aarch64.tar.gz::$REL/ytmgo_Linux_arm64.tar.gz
	sha256sums_aarch64 = $SHA_ARM

pkgname = ytmgo-bin
SRCINFO_BIN_EOF

else

# makepkg verifies the source against this. It was SKIP, which verifies
# nothing: a truncated or substituted tarball built silently. GitHub
# generates these archives on demand but the bytes for a given tag are
# stable, so the hash can be pinned like any other source.
echo "Hashing $TARBALL …" >&2
SHA256="$(curl -fsSL "$TARBALL" | sha256sum | cut -d' ' -f1)"
if [ -z "$SHA256" ] || [ "$SHA256" = "$(printf '' | sha256sum | cut -d' ' -f1)" ]; then
  echo "error: could not hash $TARBALL — refusing to generate a package that verifies nothing" >&2
  exit 1
fi
echo "  sha256 $SHA256" >&2

# ---- PKGBUILD ----
read -r -d '' PKGBUILD << PKGBUILD_EOF || true
# Maintainer: Anas <anas1412@github>
# Contributor: Anas <anas1412@github>
# Arch User Repository (AUR) package for ytmgo
# https://aur.archlinux.org/packages/ytmgo
# Auto-generated by dist/arch/generate-pkgbuild.sh

pkgname=ytmgo
pkgver=$VERSION
pkgrel=1
pkgdesc="A terminal-based YouTube Music client — search, download, queue, and play music from the keyboard"
arch=('x86_64' 'aarch64')
url="https://github.com/anas1412/ytmgo"
license=('MIT')
depends=($(printf "'%s' " "${DEPENDS[@]}" | sed 's/ $//'))
makedepends=($(printf "'%s' " "${MAKEDEPENDS[@]}" | sed 's/ $//'))
source=("\$url/archive/v\$pkgver.tar.gz")
sha256sums=('$SHA256')

build() {
  cd "\$srcdir/\$pkgname-\$pkgver"
  CGO_ENABLED=0 go build \\
    -trimpath \\
    -ldflags="-s -w -X ytmgo/internal/version.Version=v\$pkgver" \\
    -o ytmgo .
}

check() {
  cd "\$srcdir/\$pkgname-\$pkgver"
  ./ytmgo --version 2>&1 | grep -q "v\$pkgver"
}

package() {
  cd "\$srcdir/\$pkgname-\$pkgver"
  install -Dm755 ytmgo "\$pkgdir/usr/bin/ytmgo"
  install -Dm644 ytmgo-icon.png "\$pkgdir/usr/share/icons/hicolor/256x256/apps/ytmgo.png"
  # MIT carries its own copyright line, so Arch wants the text shipped
  # rather than pointed at /usr/share/licenses/common.
  install -Dm644 LICENSE "\$pkgdir/usr/share/licenses/\$pkgname/LICENSE"
  install -Dm644 /dev/stdin "\$pkgdir/usr/share/applications/ytmgo.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=ytmgo
Comment=YouTube Music from the Terminal
Exec=ytmgo
Icon=ytmgo
Terminal=true
Categories=AudioVideo;Audio;Music;Player;
Keywords=music;youtube;player;terminal;tui;audio;
StartupNotify=false
EOF
}
PKGBUILD_EOF

# ---- .SRCINFO ----
read -r -d '' SRCINFO << SRCINFO_EOF || true
pkgbase = ytmgo
	pkgdesc = A terminal-based YouTube Music client — search, download, queue, and play music from the keyboard
	pkgver = $VERSION
	pkgrel = 1
	url = https://github.com/anas1412/ytmgo
	arch = x86_64
	arch = aarch64
	license = MIT
$(printf '\tmakedepends = %s\n' "${MAKEDEPENDS[@]}")
$(printf '\tdepends = %s\n' "${DEPENDS[@]}")
	source = https://github.com/anas1412/ytmgo/archive/v$VERSION.tar.gz
	sha256sums = $SHA256

pkgname = ytmgo
SRCINFO_EOF

fi

# ---- Output ----
if [ -n "$OUT_DIR" ]; then
  mkdir -p "$OUT_DIR"
  echo "$PKGBUILD" > "$OUT_DIR/PKGBUILD"
  echo "$SRCINFO" > "$OUT_DIR/.SRCINFO"
  echo "Generated for v$VERSION:"
  echo "  $OUT_DIR/PKGBUILD"
  echo "  $OUT_DIR/.SRCINFO"
else
  echo "============================================"
  echo " PKGBUILD"
  echo "============================================"
  echo "$PKGBUILD"
  echo ""
  echo "============================================"
  echo " .SRCINFO"
  echo "============================================"
  echo "$SRCINFO"
fi
